async function auditedLane(phaseTitle, laneLabel, specId, researchPrompt, draftPromptFn) {
  const research = await agent(researchPrompt, { phase: phaseTitle, label: `${laneLabel}-research` })
  const draft = await agent(draftPromptFn(research), { phase: phaseTitle, label: `${laneLabel}-draft`, schema: DRAFT_SCHEMA })
  const audit = await agent(
    `Adversarially audit this proposed spec@1 amendment for ${specId}: ${JSON.stringify(draft)}. ` +
    `Read the ACTUAL current file at /Users/gabe/Projects/lumen/specs/${specId}.json first. Check: is every new criterion falsifiable/testable with no vague language ("should be responsive", "reasonably fast", etc.)? Do new IDs collide with existing CRIT-LUMEN-* ids already in the file? No TBDs anywhere? Do api_surface_additions have concrete Rust signatures (not "..." placeholders)? Is scope consistent with the spec's stated non_goals? Return pass:true only if it would survive a strict canon-style audit; otherwise list specific issues with suggested fixes.`,
    { phase: phaseTitle, label: `${laneLabel}-audit`, schema: AUDIT_SCHEMA }
  )
  return { lane: laneLabel, spec_id: specId, research, draft, audit }
}

async function laneA() {
  return auditedLane(
    'Lane A: Model Pricing',
    'lane-a',
    'SPEC-LUMEN-001-MODEL',
    `Research the real, currently-published token pricing (per-million-token rates for input, cached-input write, cached-input read, and output) for these 6 models via WebSearch/WebFetch: GPT-4o, DeepSeek (current R1 or V3), Qwen 2.5 Coder 32B (DashScope or standard hosted endpoint), Kimi/Moonshot (moonshot-v1-128k or current), GLM-4-Plus (Zhipu AI), Gemini 2.0 Flash and Gemini 2.0 Pro. For each, report exact rates and source URL. Then read /Users/gabe/Projects/lumen/crates/lumen-model/src/pricing.rs and report whether the ALREADY-HARDCODED ModelPricing constants for these models (look for GPT_4O, DEEPSEEK_R1, QWEN_2_5_CODER, KIMI_K1_5, GLM_4_PLUS, GEMINI_2_0_FLASH, GEMINI_2_0_PRO or similarly named consts) match your researched rates or are wrong/stale. Also read /Users/gabe/Projects/lumen/crates/lumen-model/src/economics.rs — confirm ephemeral_1h_tokens is hardcoded to 0 in TokenEconomics::calculate, meaning the "4-tier" pricing claim in docs/01-canonical-model-and-economics.md and README.md is not actually implemented (only 3 real tiers exist: uncached input, 5m cache write, cache read, plus output). Report under 400 words: per-model real rates with sources, whether code constants match, and a recommendation on whether SPEC-LUMEN-001-MODEL should (a) add a real acceptance criterion for a 1h cache tier as a near-term buildable feature, or (b) scope it out via an explicit non_goal until built.`,
    (research) => `Read /Users/gabe/Projects/lumen/specs/SPEC-LUMEN-001-MODEL.json in full to see its exact current acceptance_criteria, api_surface (10 ModelPricing constants), and existing CRIT-LUMEN-* id sequence. It currently only has acceptance criteria for 3 of the 10 pricing constants. Using this research: ${JSON.stringify(research)} — draft the missing acceptance criteria for the other pricing constants, each a falsifiable "WHEN X, THE SYSTEM SHALL Y" proposition testable against pricing.rs, with new ids continuing the existing CRIT-LUMEN-* sequence (check the real max id in the file first). Resolve the 1h-cache-tier question per the research recommendation — add either a real criterion or a non_goal, matching the spec's existing prose style exactly. Return spec_id "SPEC-LUMEN-001-MODEL".`
  )
}

