async function laneD() {
  const phaseTitle = 'Lane D: Analysis Accumulators'
  const researchGroups = [
    {
      label: 'lane-d-research-built',
      prompt: `These 5 accumulator files ALREADY EXIST and are wired into the engine but have ZERO acceptance criteria in the spec: artifacts, autonomy, context_growth, stats, tool_inventory. Read their actual implementations in full: /Users/gabe/Projects/lumen/crates/lumen-analysis/src/accumulators/artifacts.rs, autonomy.rs, context_growth.rs, stats.rs, tool_inventory.rs. For each, report exactly what it computes (its Output struct fields and the logic that populates them) in enough detail to write falsifiable acceptance criteria against the real code. Under 500 words total.`,
    },
    {
      label: 'lane-d-research-unbuilt-1',
      prompt: `These accumulators are named in SPEC-LUMEN-005-ANALYSIS's scope and README's catalog table but DO NOT EXIST as code: flow, hook_activity, pr_link, fuzzy_tools, trajectory_dag. Read the README catalog table description for each (in /Users/gabe/Projects/lumen/README.md, "Accumulators" section) and read a sibling already-built accumulator like /Users/gabe/Projects/lumen/crates/lumen-analysis/src/accumulators/mcp_affinity.rs and /Users/gabe/Projects/lumen/crates/lumen-analysis/src/traits.rs (EntryAccumulator trait) to understand the established code pattern (Output struct, update/finalize methods, what CanonicalTurn/ToolIntent fields are available to work with — check /Users/gabe/Projects/lumen/crates/lumen-model/src/turn.rs for exact turn/tool fields). For each of the 5, design a precise, buildable formula/behavior consistent with its README description and the codebase's actual data model (e.g. fuzzy_tools' README description is "Levenshtein clustering for tool name typos" — pick a concrete distance threshold; flow's is "Unbroken autonomous tool streaks and permission blocks"). Report under 600 words: for each accumulator, its Output struct shape and exact computation logic in enough detail to write falsifiable acceptance criteria.`,
    },
    {
      label: 'lane-d-research-unbuilt-2',
      prompt: `These accumulators are named in SPEC-LUMEN-005-ANALYSIS's scope and README's catalog table but DO NOT EXIST as code: attribution, timeline, otel_correlation, span_mapping. Read the README catalog table description for each (in /Users/gabe/Projects/lumen/README.md, "Accumulators" section) and read a sibling already-built accumulator like /Users/gabe/Projects/lumen/crates/lumen-analysis/src/accumulators/api_health.rs and /Users/gabe/Projects/lumen/crates/lumen-analysis/src/traits.rs (EntryAccumulator trait) to understand the established code pattern, and /Users/gabe/Projects/lumen/crates/lumen-model/src/turn.rs for available turn/tool fields, plus /Users/gabe/Projects/lumen/crates/lumen-model/src/schema.rs for SchemaCitation (relevant to otel_correlation/span_mapping which deal with mapping to external OTel spans/request ids — note lumen-model's CanonicalTranscript has no explicit otel span field today, so check whether this needs a model change or can work from existing fields). For each of the 4, design a precise, buildable formula/behavior consistent with its README description and the codebase's actual data model. Report under 600 words: for each accumulator, its Output struct shape and exact computation logic, and explicitly flag if any require a lumen-model field that doesn't exist yet (in which case propose the minimal field addition needed).`,
    },
  ]
  const researchResults = await parallel(researchGroups.map((g) => () =>
    agent(g.prompt, { phase: phaseTitle, label: g.label })
  ))

  const planText = await (async () => {
    return agent(
      `Read /Users/gabe/Projects/lumen/specs/PLAN-LUMEN-005-ANALYSIS.json in full and /Users/gabe/Projects/lumen/specs/SPEC-LUMEN-005-ANALYSIS.json in full. Confirm which acceptance criteria exist in the spec but appear in no task's covers_criteria list in the plan (earlier audit found CRIT-060, 062, 064, 069 orphaned — verify exact ids and what each criterion is about). Report under 200 words: the exact orphaned criteria ids, what each requires, and which existing task (by id) each should logically be added to (or whether a new task is needed).`,
      { phase: phaseTitle, label: 'lane-d-research-plan-orphans' }
    )
  })()

  const draft = await agent(
    `Read /Users/gabe/Projects/lumen/specs/SPEC-LUMEN-005-ANALYSIS.json in full for its exact current content and CRIT-LUMEN-* id sequence (it names 22 accumulators in scope but only 8 have acceptance criteria today). Using this research on the 5 built-but-uncovered accumulators: ${JSON.stringify(researchResults[0])} — and this research on 5 unbuilt accumulators: ${JSON.stringify(researchResults[1])} — and this research on 4 more unbuilt accumulators: ${JSON.stringify(researchResults[2])} — draft acceptance criteria for ALL 14 gap accumulators (artifacts, autonomy, context_growth, stats, tool_inventory, flow, hook_activity, pr_link, fuzzy_tools, trajectory_dag, attribution, timeline, otel_correlation, span_mapping), each a falsifiable proposition grounded in the research. Include api_surface_additions for any that need a new lumen-model field per the research flags. New ids continue the existing CRIT-LUMEN-* sequence. In other_field_changes, also include a clear plan describing exactly how to fix PLAN-LUMEN-005-ANALYSIS.json's orphaned criteria per this research: ${JSON.stringify(planText)} — name which task_id each orphaned criterion id should be added to. Return spec_id "SPEC-LUMEN-005-ANALYSIS".`,
    { phase: phaseTitle, label: 'lane-d-draft', schema: DRAFT_SCHEMA }
  )
  const audit = await agent(
    `Adversarially audit this proposed spec@1 amendment for SPEC-LUMEN-005-ANALYSIS covering 14 accumulators: ${JSON.stringify(draft)}. Read the actual current file at /Users/gabe/Projects/lumen/specs/SPEC-LUMEN-005-ANALYSIS.json first. Check every one of the 14: is the criterion falsifiable and specific (exact thresholds/formulas, not "detects patterns")? No id collisions with existing criteria? Do api_surface_additions have concrete Rust signatures? Is the O(N) single-pass, zero-heap-allocation invariant (AGENTS.md rule 3) respected by the described logic for each? Return pass:true only if solid; otherwise list specific issues with suggested fixes, one per accumulator that has a problem.`,
    { phase: phaseTitle, label: 'lane-d-audit', schema: AUDIT_SCHEMA }
  )
  return { lane: 'D', spec_id: 'SPEC-LUMEN-005-ANALYSIS', research: researchResults, planText, draft, audit }
}

