async function laneH() {
  const phaseTitle = 'Lane H: Vision Docs'
  const research = await agent(
    `Read the actual /Users/gabe/Projects/lumen/LICENSE file in full, and /Users/gabe/Projects/lumen/AGENTS.md's licensing table. Then read /Users/gabe/Projects/lumen/docs/09-enterprise-adoption-and-commercial-strategy.md's license table in full and diff it against reality: it adds crates (lumen-store as FSL, lumen-daemon, lumen-insights) that don't exist yet or aren't in the real LICENSE, and describes per-crate FSL carve-outs different from the actual single Excluded Purpose clause. Also skim docs/07-data-presentation-and-ui-design-standard.md, docs/08-lumen-mac-swift-native-app-blueprint.md, and docs/10-the-six-generational-leaps.md for their current opening framing (first ~10 lines each) to see if they already carry any "status" disclaimer. Report under 350 words: (1) the exact corrected license table matching the real LICENSE file and AGENTS.md (only list crates that actually exist today: lumen-model, lumen-session as MIT/Apache-2.0; lumen-cli, lumen-analysis, lumen-pattern as FSL-1.1-MIT; mark lumen-store/lumen-daemon/lumen-insights as "planned, not yet licensed" rather than asserting a license for nonexistent crates), and (2) exact proposed banner text (2-3 sentences) to prepend to each of docs 07/08/09/10 marking them as vision/roadmap, not implementation status, distinguishing them from docs 01-06.`,
    { phase: phaseTitle, label: 'lane-h-research' }
  )
  const draft = await agent(
    `Using this research: ${JSON.stringify(research)} — produce the exact proposed_changes text for 4 separate doc amendments: (1) docs/09-enterprise-adoption-and-commercial-strategy.md's corrected license table (full replacement markdown table), (2) a vision-status banner for docs/07-data-presentation-and-ui-design-standard.md, (3) a vision-status banner for docs/08-lumen-mac-swift-native-app-blueprint.md, (4) a vision-status banner for docs/10-the-six-generational-leaps.md. Return one object per doc as an array in other_field_changes (as literal text, clearly labeled per doc_path), and set spec_id to "DOCS-VISION-BANNERS" and summary describing all 4 changes.`,
    { phase: phaseTitle, label: 'lane-h-draft', schema: DRAFT_SCHEMA }
  )
  return { lane: 'H', research, draft }
}

