45	impl TrajectoryGraph {
46	    pub fn new() -> Self {
47	        Self { graph: DiGraph::new(), last_node: None, total_mutations: 0, total_reads: 0 }
48	    }
49	
50	    pub fn push_tool(&mut self, node: ToolNode) -> NodeIndex {
51	        if node.is_mutation {
52	            self.total_mutations += 1;
53	        } else {
54	            self.total_reads += 1;
55	        }
56	
57	        let current = self.graph.add_node(node);
58	        if let Some(prev) = self.last_node {
59	            self.graph.add_edge(prev, current, ());
60	        }
61	        self.last_node = Some(current);
62	        current
63	    }
64	
65	    pub fn detect_circular_loops(&self) -> Vec<CircularLoopAnomaly> {
66	        let mut anomalies = Vec::new();
67	        let sccs = tarjan_scc(&self.graph);
68	
69	        for component in sccs {
70	            if component.len() >= 3 {
71	                let first_symbol = self.graph[component[0]].target_symbol.clone();
72	                let is_redundant = component
73	                    .iter()
74	                    .all(|idx| self.graph[*idx].target_symbol == first_symbol && !self.graph[*idx].is_mutation);
75	
76	                if is_redundant {
77	                    if let Some(sym) = first_symbol {
78	                        anomalies.push(CircularLoopAnomaly { symbol: sym, cycle_depth: component.len() });
79	                    }
80	                }
81	            }
82	        }
83	        anomalies
84	    }
85	
86	    pub fn calculate_efficiency(&self) -> f32 {
87	        let total = self.total_mutations + self.total_reads;
88	        if total == 0 {
89	            return 1.0;
90	        }
91	        (self.total_mutations as f32 + (self.total_reads as f32 * 0.5)) / (total as f32)
92	    }
93	
94	    pub fn calculate_monotonicity(&self) -> f32 {
95	        let total_nodes = self.graph.node_count();
96	        if total_nodes == 0 {
97	            return 1.0;
98	        }
99	        let anomalies = self.detect_circular_loops();
100	        let loop_nodes: usize = anomalies.iter().map(|a| a.cycle_depth).sum();
101	        let loop_penalty = (loop_nodes as f32 / total_nodes as f32).min(1.0);
102	
103	        (1.0 - loop_penalty).max(0.0)
104	    }
105	}
