107	/// Computes Argument Grounding Score G = (Grounded Tool Args) / (Total Invocations).
108	pub fn compute_grounding_score(transcript: &CanonicalTranscript) -> f32 {
109	    let mut total_tools = 0;
110	    let mut grounded_tools = 0;
111	
112	    for turn in &transcript.turns {
113	        for call in &turn.tool_calls {
114	            total_tools += 1;
115	            match &call.intent {
116	                ToolIntent::FileRead { path, .. } | ToolIntent::FileEdit { path, .. } => {
117	                    if !path.is_empty() {
118	                        grounded_tools += 1;
119	                    }
120	                }
121	                ToolIntent::CodeSearch { query, .. } => {
122	                    if !query.is_empty() {
123	                        grounded_tools += 1;
124	                    }
125	                }
126	                _ => {
127	                    grounded_tools += 1;
128	                }
129	            }
130	        }
131	    }
132	
133	    if total_tools == 0 {
134	        1.0
135	    } else {
136	        grounded_tools as f32 / total_tools as f32
137	    }
138	}
139	
140	/// Computes Error Recovery Index R = (Adaptive Error Pivots) / (Total Error Events).
141	pub fn compute_recovery_index(transcript: &CanonicalTranscript) -> f32 {
142	    let mut error_events = 0;
143	    let mut adaptive_pivots = 0;
144	
145	    for i in 0..transcript.turns.len() {
146	        let turn = &transcript.turns[i];
147	        let has_error = turn.tool_results.iter().any(|r| r.is_error);
148	
149	        if has_error {
150	            error_events += 1;
151	            if i + 1 < transcript.turns.len() {
152	                let next_turn = &transcript.turns[i + 1];
153	                let next_has_error = next_turn.tool_results.iter().any(|r| r.is_error);
154	                if !next_has_error {
155	                    adaptive_pivots += 1;
156	                }
157	            }
158	        }
159	    }
160	
161	    if error_events == 0 {
162	        1.0
163	    } else {
164	        adaptive_pivots as f32 / error_events as f32
165	    }
166	}
