1	use compact_str::CompactString;
2	use lumen_model::CanonicalTurn;
3	use serde::{Deserialize, Serialize};
4	use std::cmp::Reverse;
5	use std::collections::{BTreeMap, BTreeSet};
6	
7	use crate::traits::EntryAccumulator;
8	
9	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
10	pub struct ToolCluster {
11	    pub canonical: CompactString,
12	    pub variants: Vec<(CompactString, usize)>,
13	}
14	
15	#[derive(Debug, Clone, Serialize, Deserialize, Default)]
16	pub struct FuzzyToolsMetrics {
17	    pub clusters: Vec<ToolCluster>,
18	    pub typo_call_count: usize,
19	    pub typo_rate: f64,
20	    pub total_tool_calls: usize,
21	}
22	
23	#[derive(Debug, Default, Clone)]
24	pub struct FuzzyToolsAccumulator {
25	    pub counts: BTreeMap<CompactString, usize>,
26	    pub total_tool_calls: usize,
27	}
28	
29	impl EntryAccumulator for FuzzyToolsAccumulator {
30	    type Output = FuzzyToolsMetrics;
31	
32	    fn update(&mut self, entry: &CanonicalTurn) {
33	        for call in &entry.tool_calls {
34	            *self.counts.entry(call.tool_name.clone()).or_insert(0) += 1;
35	        }
36	        self.total_tool_calls += entry.tool_calls.len();
37	    }
38	
39	    fn finalize(self) -> Self::Output {
40	        let mut sorted: Vec<(CompactString, usize)> = self.counts.into_iter().collect();
41	        sorted.sort_by(|a, b| Reverse(a.1).cmp(&Reverse(b.1)).then_with(|| a.0.cmp(&b.0)));
42	
43	        let mut visited: BTreeSet<CompactString> = BTreeSet::new();
44	        let mut clusters: Vec<ToolCluster> = Vec::new();
45	
46	        for i in 0..sorted.len() {
47	            let canonical = sorted[i].0.clone();
48	            if visited.contains(&canonical) {
49	                continue;
50	            }
51	            visited.insert(canonical.clone());
52	
53	            let mut variants: Vec<(CompactString, usize)> = Vec::new();
54	            for (candidate, count) in sorted.iter().skip(i + 1) {
55	                if visited.contains(candidate) {
56	                    continue;
57	                }
58	                let threshold = if candidate.len() < 5 { 1 } else { 2 };
59	                let distance = levenshtein(&canonical, candidate);
60	                if distance > 0 && distance <= threshold {
61	                    visited.insert(candidate.clone());
62	                    variants.push((candidate.clone(), *count));
63	                }
64	            }
65	
66	            clusters.push(ToolCluster { canonical, variants });
67	        }
68	
69	        let typo_call_count: usize =
70	            clusters.iter().map(|c| c.variants.iter().map(|(_, count)| count).sum::<usize>()).sum();
71	
72	        let typo_rate =
73	            if self.total_tool_calls == 0 { 0.0 } else { typo_call_count as f64 / self.total_tool_calls as f64 };
74	
75	        FuzzyToolsMetrics { clusters, typo_call_count, typo_rate, total_tool_calls: self.total_tool_calls }
76	    }
77	}
78	
79	fn levenshtein(a: &str, b: &str) -> usize {
80	    let a: Vec<char> = a.chars().collect();
81	    let b: Vec<char> = b.chars().collect();
82	    let (m, n) = (a.len(), b.len());
83	
84	    let mut dp = vec![vec![0usize; n + 1]; m + 1];
85	    for (i, row) in dp.iter_mut().enumerate().take(m + 1) {
86	        row[0] = i;
87	    }
88	    for (j, cell) in dp[0].iter_mut().enumerate() {
89	        *cell = j;
90	    }
91	
92	    for i in 1..=m {
93	        for j in 1..=n {
94	            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
95	            dp[i][j] = (dp[i - 1][j] + 1).min(dp[i][j - 1] + 1).min(dp[i - 1][j - 1] + cost);
96	        }
97	    }
98	
99	    dp[m][n]
100	}
